var n=`0063-lokse`;var t=`world-0063`;var o=`SK`;var s=`eastern-europe`;var a=4;var r=56;var l={en:`Lokše`,ua:`Локші`};var d={en:`A classic dish from Slovakia, featuring potato, all-purpose flour, lard, unsalted butter. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Словаччина. Основні складники: картопля, пшеничне борошно універсальне, смалець, несолоне вершкове масло. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`potato`,650,`g`],[`water`,1e3,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`all-purpose-flour`,185,`g`],[`table-salt`,4,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`lard`,45,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,35,`g`]]}];var g={slug:n,id:t,country:`SK`,region:s,servings:4,minutes:56,title:l,text:d,steps:u};export{o as country,g as default,t as id,r as minutes,s as region,a as servings,n as slug,u as steps,d as text,l as title};